#[derive(Clone, Copy)]
pub struct UnicodeEmoji17RgiRoleAuditTestSupport;

impl UnicodeEmoji17RgiRoleAuditTestSupport {

    pub fn unicode_emoji17_rgi_role_audit_test_support_to_unicode_string(code_points: &UStr) -> UString {
        let mut out_b = UString::new();
        {
            let _g1 = u_string::split(&code_points, &UString::from(" "));
            for hex in &_g1 {
                let cp = u_string::parse_i32(&({ let mut __s = UString::new(); __s += &(UString::from("0x")); __s += hex.as_ustr(); __s }));
                {
                    let x = if cp.unwrap_or_default() > 0xFFFF { u_string::from_units(&[0xD800 + (((cp.unwrap_or_default()) - 0x10000) >> 10) as u16, 0xDC00 + (((cp.unwrap_or_default()) - 0x10000) & 0x3FF) as u16]) } else { u_string::from_units(&[(cp.unwrap_or_default()) as u16]) };
                    out_b += &(x.to_string());
                }
            }
        }
        return out_b;
    }
}
